use std::sync::Arc;

use crate::domain::services::{
    entity_details::EntityDetailsService, entity_search::EntitySearchService,
    rankings::RankingsService,
};

#[derive(Clone)]
/// State required to run the exposed app
pub struct AppState<E: EntitySearchService, D: EntityDetailsService, R: RankingsService> {
    /// Entity search service
    pub entity_search_service: Arc<E>,
    /// Current-term rankings service
    pub rankings_service: Arc<R>,
    /// Entity detail service
    pub entity_details_service: Arc<D>,
}
//! Contains search entity models

use serde::Serialize;
use thiserror::Error;

use crate::domain::models::{funder::Funder as FunderDetails, parliament_member::ParliamentMember};

/// Default primary search threshold.
pub const DEFAULT_SEARCH_STRICTNESS: f32 = 0.8;

const MAX_STRICTNESS: f32 = 1_f32;
const MIN_STRICTNESS: f32 = 0_f32;
const MIN_ENTRIES: u8 = 1;

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
/// Name that supplied a search result's winning score.
pub enum SearchMatchSource {
    /// The canonical name won, including equal scores.
    Name,
    /// An observed alias scored higher than the canonical name.
    Alias {
        /// Original observed spelling.
        name: String,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Canonical funder identity and its search match provenance.
pub struct FunderSearchMatch {
    funder: FunderDetails,
    source: SearchMatchSource,
}

impl FunderSearchMatch {
    #[must_use]
    /// Creates a search result for a canonical identity.
    pub const fn new(funder: FunderDetails, source: SearchMatchSource) -> Self {
        Self { funder, source }
    }

    #[must_use]
    /// Canonical funder.
    pub const fn funder(&self) -> &FunderDetails {
        &self.funder
    }

    #[must_use]
    /// Winning match source.
    pub const fn source(&self) -> &SearchMatchSource {
        &self.source
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity kind
pub enum Entity {
    /// Company entity
    Funder(FunderSearchMatch),
    /// Member entitiy
    ParliamentMember(ParliamentMember),
}

impl Entity {
    #[must_use]
    /// Entity name
    pub fn name(&self) -> &str {
        match self {
            Self::Funder(kind) => kind.funder().name(),
            Self::ParliamentMember(mp) => mp.name(),
        }
    }

    #[must_use]
    /// Entity kind
    pub const fn kind(&self) -> &str {
        match self {
            Self::Funder(_) => "Funder",
            Self::ParliamentMember(_) => "MP",
        }
    }

    #[must_use]
    /// Funder kind
    pub fn funder_kind(&self) -> Option<&str> {
        match self {
            Self::Funder(kind) => Some(kind.funder().kind()),
            Self::ParliamentMember(_) => None,
        }
    }
}

impl From<&ParliamentMember> for Entity {
    fn from(value: &ParliamentMember) -> Self {
        Self::ParliamentMember(value.clone())
    }
}

impl From<&FunderSearchMatch> for Entity {
    fn from(value: &FunderSearchMatch) -> Self {
        Self::Funder(value.clone())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity name
pub struct EntityName(String);

#[derive(Clone, Debug, PartialEq)]
/// Data required to search entities
pub struct EntitySearchRequest {
    term: String,
    strictness: f32,
    max_entries: u8,
}

impl EntitySearchRequest {
    #[must_use]
    /// Search term
    pub const fn term(&self) -> &str {
        self.term.as_str()
    }

    #[must_use]
    /// Search strictness
    pub const fn strictness(&self) -> f32 {
        self.strictness
    }

    #[must_use]
    /// Max result set
    pub const fn max_entries(&self) -> u8 {
        self.max_entries
    }
}

impl EntitySearchRequest {
    /// Creates new instance with [`MAX_STRICTNESS`]
    ///
    /// # Errors
    /// - See [`Self::new_with_strictness`]
    pub fn new_strict(term: String, max_entries: u8) -> Result<Self, EntitySearchError> {
        Self::new_with_strictness(term, max_entries, MAX_STRICTNESS)
    }
    /// Creates new instance with variable strictness
    ///
    /// # Errors
    /// - Term too short
    /// - Too few entries
    /// - Invalid strictness
    pub fn new_with_strictness(
        term: String,
        max_entries: u8,
        strictness: f32,
    ) -> Result<Self, EntitySearchError> {
        // It will be a u8
        #[allow(clippy::cast_possible_truncation)]
        if term.trim().len() < 3 {
            return Err(EntitySearchError::InvalidTerm(term.trim().len() as u8));
        }
        if max_entries < MIN_ENTRIES {
            return Err(EntitySearchError::TooFewEntries);
        }
        if !strictness.is_finite() || strictness < MIN_STRICTNESS || strictness > MAX_STRICTNESS {
            return Err(EntitySearchError::InvalidStrictness(strictness));
        }
        Ok(Self {
            term,
            strictness,
            max_entries,
        })
    }
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntitySearchError {
    /// Unexpected runtime errors, usually from the database
    #[error("unexpected error occurred: {0}")]
    UnexpectedError(String),

    /// Term too short for generating valid search results
    #[error("term must be at last three characters long; received {0}")]
    InvalidTerm(u8),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    TooFewEntries,

    /// Invalid strictness value
    #[error("strictness must be between {MIN_STRICTNESS} and {MAX_STRICTNESS}; get {0}")]
    InvalidStrictness(f32),
}

#[cfg(test)]
mod strictness {
    use super::EntitySearchRequest;

    #[test]
    fn rejects_non_finite_thresholds() {
        for threshold in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            assert!(
                EntitySearchRequest::new_with_strictness("West".into(), 10, threshold).is_err()
            );
        }
    }
}

/// Primary funder matches and eligibility before the result limit.
#[derive(Clone)]
pub struct FunderSearchResults {
    /// Ranked, limited canonical identities.
    pub matches: Vec<(
        FunderSearchMatch,
        crate::domain::models::search_similarity::SearchSimilarity,
    )>,
    /// Whether any qualifying individual exists, including outside the limit.
    pub has_qualifying_individual: bool,
}

/// Ranking for a phonetic match, independent of primary similarity.
#[derive(Clone)]
pub struct PhoneticRank {
    distance: u32,
    similarity: crate::domain::models::search_similarity::SearchSimilarity,
}

impl PhoneticRank {
    /// Creates a rank from a nonnegative token edit distance.
    #[must_use]
    pub const fn new(
        distance: u32,
        similarity: crate::domain::models::search_similarity::SearchSimilarity,
    ) -> Self {
        Self {
            distance,
            similarity,
        }
    }

    /// Orders smaller edit distances first, then greater trigram similarity.
    #[must_use]
    pub fn compare(&self, other: &Self) -> std::cmp::Ordering {
        self.distance
            .cmp(&other.distance)
            .then_with(|| other.similarity.value().total_cmp(&self.similarity.value()))
    }
}
<script lang="ts">
  import {
    Icon,
    SearchField,
    Spinner,
    SkeletonRows,
    ResultRow,
    HighlightedText,
    MessageState,
    Button,
    Badge,
  } from "./lib/ui";
  import EntityIndicator from "./lib/EntityIndicator.svelte";
  import {
    entityHref,
    highlightName,
    searchConfiguration,
    type Entity,
  } from "./lib/search";

  import { onMount, untrack } from "svelte";
  import { page } from "$app/state";
  import { goto, afterNavigate } from "$app/navigation";
  import posthog from "posthog-js";
  import { posthogLogger } from "./lib/posthog-logger";
  import type { PageModel, SearchResult } from "./lib/page";
  let { model }: { model: Extract<PageModel, { kind: "search" }> } = $props();
  type SearchState = SearchResult | { status: "loading"; term: string };
  type SearchFocusShortcut =
    { modifier: "meta"; hint: "⌘ K" } | { modifier: "ctrl"; hint: "Ctrl K" };
  let searchFocusShortcut = $state<SearchFocusShortcut>({
    modifier: "ctrl",
    hint: "Ctrl K",
  });
  onMount(() => {
    if (/Mac/i.test(navigator.platform))
      searchFocusShortcut = { modifier: "meta", hint: "⌘ K" };
  });
  let query = $state(untrack(() => model.query));
  afterNavigate(({ type }) => {
    if (type === "popstate" || type === "link") {
      query = page.url.searchParams.get("q") ?? "";
    }
  });
  let composing = $state(false);
  let attempt = $state(0);
  let input = $state<HTMLInputElement>();
  let pending = $state(false);
  const term = $derived(query.trim());
  const charactersNeeded = $derived(
    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
  );
  const searchState = $derived<SearchState>(
    composing || charactersNeeded
      ? { status: "idle" }
      : pending || model.query.trim() !== term
        ? { status: "loading", term }
        : model.result,
  );
  const announcement = $derived(
    searchState.status === "loading"
      ? "Searching…"
      : searchState.status === "success"
        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
        : "",
  );

  $effect(() => {
    const currentTerm = term;
    const currentAttempt = attempt;
    if (
      composing ||
      [...currentTerm].length < searchConfiguration.minimumCharacters
    )
      return;
    if (!currentAttempt && untrack(() => model.query.trim() === currentTerm))
      return;
    let current = true;
    const timer = setTimeout(
      async () => {
        const url = new URL(window.location.href);
        url.searchParams.set("q", currentTerm);
        const queryLength = [...currentTerm].length;
        posthog.capture("search_submitted", { query_length: queryLength });
        posthogLogger.info("search submitted", { query_length: queryLength });
        pending = true;
        try {
          await goto(url, { replace: true, reset: false, refreshAll: true });
        } finally {
          if (current) pending = false;
        }
      },
      currentAttempt ? 0 : searchConfiguration.debounceMs,
    );
    return () => {
      current = false;
      pending = false;
      clearTimeout(timer);
    };
  });

  function updateQuery(value: string) {
    attempt = 0;
    query = value;
    const url = new URL(window.location.href);
    if (value.trim()) url.searchParams.set("q", value.trim());
    else url.searchParams.delete("q");
    void goto(url, {
      shallow: true,
      replace: true,
      reset: false,
      state: page.state,
    });
  }

  function clearSearch() {
    updateQuery("");
    input?.focus();
  }

  function retrySearch() {
    posthogLogger.warn("search retry requested", {
      query_length: [...term].length,
    });
    attempt += 1;
  }

  function shortcut(event: KeyboardEvent) {
    if (
      event.key.toLowerCase() === "k" &&
      !event.defaultPrevented &&
      !event.isComposing &&
      !composing &&
      !event.shiftKey &&
      !event.altKey &&
      (searchFocusShortcut.modifier === "meta"
        ? event.metaKey && !event.ctrlKey
        : event.ctrlKey && !event.metaKey)
    ) {
      event.preventDefault();
      input?.focus();
      return;
    }
    const target = event.target;
    const editing =
      target instanceof HTMLElement &&
      (target.isContentEditable ||
        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
    if (
      event.key === "/" &&
      !editing &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      event.preventDefault();
      input?.focus();
    }
    if (event.key === "Escape" && target === input && !event.isComposing)
      clearSearch();
  }

  function atLimit(entities: Entity[]) {
    return ["MP", "Funder"].some(
      (kind) =>
        entities.filter((entity) => entity.kind === kind).length >=
        searchConfiguration.maxEntriesPerType,
    );
  }
</script>

<svelte:window onkeydown={shortcut} />

<main id="search">
